% interface to colectedStral command linefunction fBridge4(funcName,hasInput,hasOutput,funcArgs)% gets the input as JSON coded data/structure and...% split targeted Octave calling function and...% if input argument is provided or...% if resulted output is requested, would be sent back to colectedStral% never use disp function in your code (adds newline)disp('fBridge is talking:')%suppress_verbose_help_message(1,'local');program_name ()program_invocation_name ()cmdline_options ()if nargin>=3	% normal call	disp(['i Got: ',funcName,'/',num2str(hasInput),'/',num2str(hasOutput)])	if nargin==4		disp('functionArgs:');		funcArgs	else		disp('no input args provided')	end%if
else	disp(['failed to get input args: #',num2str(nargin)])	cmdArgs 	= argv()	funcName  = cmdArgs{1}	hasInput  = str2num(cmdArgs{2})	hasOutput = str2num(cmdArgs{3})	whos	pwd	addpath([pwd,'\testy'])end%if%% INPUT---------------------------------------------------------------	if hasInput==0		% not any input is passed (& required)	elseif nargin>3		% input args are passed by value (during call)	elseif hasInput==1		% get the input argumans		colectedStr = '';% empty string for input data from colectedStrAL		%% get and combine strings into one		while true		%% read the input from terminal		terminalStr = fgets(stdin);			if terminalStr == -1				% nothing left to add				%% JSON is collected as string from CMD input				myData = jsondecode(colectedStr);% converted back to struct()				% find the input argumans				funcArgs = myData.args;% cell of anything				clearvars('colectedStr','terminalStr');% free memory				break;% exit			else				% continue to grab the data as input				colectedStr = [colectedStr,terminalStr];% append			end%if		end%while	end%if%% CALL--------------------------------------------------------------	%try		if hasOutput==0 && hasInput==0		% neither input has been provided nor output is requested			feval(funcName);		elseif hasOutput==0 && hasInput==1		% no output is requested			feval(funcName,funcArgs{:});% input only		elseif hasOutput==1 && hasInput==0		% no input is provided but the output is expected			[logStr,retVal]  = evalc([funcName,'()']);% output only		elseif hasOutput==1 && hasInput==1		% both input and output			[logStr,retVal]  = evalc([funcName,'(funcArgs{:})'])% output & input		else		% never			error(['h-case{ input No=',num2str(hasOutput),'} {output No=',num2str(hasOutput),'}']);		end%if	%catch		% exit with an error message		%error(["error in call process: ", lasterror]);	%end%try%% RETURN-----------------------------------------------------------	if hasOutput==1		jData = jsonencode(retVal);		printf("%s", jData);% send back to terminal	end%ifend%function